class Queue:
    def __init__(self, capacity):
        self.data = [None] * capacity
        self.head = self.tail = self.count = 0
    def put(self, value):
        if self.count == len(self.data) - 1:
            return False
        self.data[self.tail] = value
        self.tail += 1
        self.count += 1
        return True
    def get(self):
        value = self.data[self.head]
        self.head += 1
        return value
